<?php
require __DIR__.'/../config/koneksi.php';require_login();$from=$_GET['from']??'';$to=$_GET['to']??'';$search=trim($_GET['q']??'');$sql='SELECT t.*,u.nama kasir FROM transaksi t LEFT JOIN users u ON u.id=t.user_id WHERE 1=1';$params=[];if($from){$sql.=' AND DATE(t.tanggal)>=?';$params[]=$from;}if($to){$sql.=' AND DATE(t.tanggal)<=?';$params[]=$to;}if($search!==''){$sql.=' AND (t.kode_transaksi LIKE ? OR u.nama LIKE ?)';$params[]="%$search%";$params[]="%$search%";}$sql.=' ORDER BY t.id DESC LIMIT 300';$q=$pdo->prepare($sql);$q->execute($params);$rows=$q->fetchAll();page_start('Riwayat Transaksi');?>
<div class="panel-card"><form class="row g-2 mb-3"><div class="col-md-3"><input class="form-control" type="date" name="from" value="<?=e($from)?>"></div><div class="col-md-3"><input class="form-control" type="date" name="to" value="<?=e($to)?>"></div><div class="col-md-4"><input class="form-control" name="q" placeholder="Cari kode transaksi/kasir" value="<?=e($search)?>"></div><div class="col-md-2"><button class="btn btn-primary w-100">Filter</button></div></form><div class="table-responsive"><table class="table modern-table"><thead><tr><th>Kode</th><th>Tanggal</th><th>Kasir</th><th>Total</th><th>Bayar</th><th>Kembalian</th><th>Struk</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['kode_transaksi'])?></td><td><?=e($r['tanggal'])?></td><td><?=e($r['kasir']??'-')?></td><td><?=rupiah($r['total'])?></td><td><?=rupiah($r['bayar'])?></td><td><?=rupiah($r['kembalian'])?></td><td><a class="btn btn-sm btn-outline-primary" href="struk.php?id=<?=$r['id']?>">Lihat</a></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="7" class="text-center muted">Belum ada transaksi yang sesuai.</td></tr><?php endif; ?></tbody></table></div></div><?php page_end(); ?>
